import hashlib
import json
import uuid
from datetime import datetime, UTC
from pathlib import Path

import torch
from safetensors.torch import save_file

from klineage.backend import detect_backend

ROOT = Path(__file__).resolve().parent
SEED = 20260903
BATCH = 32
VOCAB = 128256
TOP_P = 0.9


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    input_path = ROOT / "inputs/top_p.safetensors"
    assert not input_path.exists(), "Inputs are already frozen"
    backend = detect_backend()
    assert torch.cuda.get_device_capability() == (9, 0)
    assert "H100" in torch.cuda.get_device_name()

    # Generate once on CPU; later runs load these exact bytes.
    torch.set_num_threads(1)
    generator = torch.Generator(device="cpu").manual_seed(SEED)
    logits = torch.randn((BATCH, VOCAB), generator=generator, dtype=torch.float32)
    probs = torch.softmax(logits, dim=-1)
    top_p = torch.full((BATCH,), TOP_P, dtype=torch.float32)
    assert torch.isfinite(probs).all() and (probs > 0).all()
    save_file(
        {"probs": probs, "top_p": top_p}, str(input_path),
        metadata={"klineage.strides": json.dumps({"probs": [VOCAB, 1], "top_p": [1]})},
    )

    definition = {
        "name": "top_p",
        "op_type": "top_p_renorm_probs",
        "axes": {"B": {"type": "const", "value": BATCH},
                 "V": {"type": "const", "value": VOCAB}},
        "inputs": {
            "probs": {"shape": ["B", "V"], "dtype": "float32",
                      "description": "Dense row probabilities; strides [128256, 1]."},
            "top_p": {"shape": ["B"], "dtype": "float32",
                      "description": "Per-row threshold; stride [1]; frozen to float32(0.9)."},
        },
        "outputs": {
            "renorm_probs": {"shape": ["B", "V"], "dtype": "float32",
                             "description": "Filtered, normalized probabilities; strides [128256, 1]."},
        },
        "reference": (ROOT / "reference.py").read_text(),
    }
    workload = {
        "uuid": str(uuid.uuid5(uuid.NAMESPACE_OID, digest(input_path))),
        "axes": {},
        "inputs": {
            name: {"type": "safetensors", "path": "inputs/top_p.safetensors", "tensor_key": name}
            for name in definition["inputs"]
        },
    }
    definition_path = ROOT / "definitions/top_p.json"
    workload_path = ROOT / "workloads/top_p.jsonl"
    definition_path.write_text(json.dumps(definition, indent=2) + "\n")
    workload_path.write_text(json.dumps({"definition": "top_p", "workload": workload}) + "\n")

    manifest = {
        "frozen_at": datetime.now(UTC).isoformat(),
        "seed": SEED, "distribution": "CPU torch.randn float32 N(0,1), one row softmax",
        "torch_version": torch.__version__, "cpu_threads": 1,
        "language": backend.language, "platform": backend.platform(),
        "device": torch.cuda.get_device_name(),
        "top_p_float32": top_p[0].item(),
        "probability_range": [probs.min().item(), probs.max().item()],
        "row_sum_range": [probs.double().sum(-1).min().item(), probs.double().sum(-1).max().item()],
        "sha256": {str(path.relative_to(ROOT)): digest(path)
                   for path in [input_path, definition_path, workload_path, ROOT / "reference.py"]},
    }
    (ROOT / "inputs/manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")
    print(json.dumps(manifest, indent=2))


if __name__ == "__main__":
    main()
