import json
from pathlib import Path

import torch
from safetensors.torch import load_file

from reference import check_outputs, run

ROOT = Path(__file__).resolve().parent
TOLERANCE = 1e-2


def main():
    # Binary fractions give an exact crossing, equality, and boundary tie.
    probs = torch.tensor([[0.5, 0.25, 0.125, 0.0625, 0.0625]]).repeat(3, 1)
    threshold = torch.tensor([0.8, 0.875, 0.9])
    manual = torch.tensor([[4/7, 2/7, 1/7, 0, 0],
                           [4/7, 2/7, 1/7, 0, 0],
                           [0.5, 0.25, 0.125, 0.0625, 0.0625]])
    actual = run(probs, threshold)
    torch.testing.assert_close(actual, manual, rtol=1e-6, atol=1e-6)
    check_outputs(actual, manual)

    frozen = load_file(str(ROOT / "inputs/top_p.safetensors"))
    expected = run(frozen["probs"], frozen["top_p"])
    check_outputs(expected, expected)
    check_outputs((expected,), (expected,))
    moved = expected.clone()
    retained = (expected[0] > 0).nonzero()[0, 0].item()
    excluded = (expected[0] == 0).nonzero()[0, 0].item()
    moved[0, excluded], moved[0, retained] = expected[0, retained], 0
    cases = {"all_zero": torch.zeros_like(expected),
             "unchanged_input": frozen["probs"], "moved_support": moved}
    evidence = {"small_manual_example_passed": True, "valid_output_passed": True,
                "valid_container_passed": True, "adversarial": {}}
    for name, candidate in cases.items():
        numerical = torch.allclose(candidate, expected, rtol=TOLERANCE, atol=TOLERANCE)
        try:
            check_outputs(candidate, expected)
        except AssertionError as error:
            evidence["adversarial"][name] = {"elementwise_allclose_passed": numerical,
                                             "rejected": True, "reason": str(error)}
            continue
        raise AssertionError(f"Checker accepted {name}")

    evidence["support_counts"] = (expected > 0).sum(-1).tolist()
    path = ROOT.parent / "baseline/evaluations/reference_checks.json"
    path.write_text(json.dumps(evidence, indent=2) + "\n")
    print(json.dumps(evidence, indent=2))


if __name__ == "__main__":
    main()

