/bin/bash -lc "cat > submission/solution/kernel.cu <<'EOF'
// Top-p renormalization over dense row probabilities.
//
// Each row is solved by a three-level radix select over the monotone unsigned
// encoding of the float32 key. Level histograms accumulate float64 sums, so the
// selection matches the float64 cumulative reference used for the cutoff.
//
//   key        : order preserving uint32 of the probability
//   level 0    : bins over bits [31:21]   (2048 bins)
//   level 1    : bins over bits [20:11]   (1024 bins, inside the level 0 bin)
//   level 2    : bins over bits [10:0]    (2048 bins, exactly one key per bin)
//
// level 0 histogram ----> crossing bin b0, sum above A0
//          level 1 histogram (filtered to b0) ----> crossing bin b1, A1
//                   level 2 histogram (filtered to b0,b1) ----> exact key, A2
//                            emit: out = p / sum{p >= cutoff} or 0
#include <torch/extension.h>

#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>

namespace {

constexpr int kThreads = 1024;
constexpr int kLanes = 32;
constexpr int kWarps = kThreads / kLanes;

// Radix split of the 32-bit monotone key.
constexpr int kRadix0 = 11;
constexpr int kRadix1 = 10;
constexpr int kRadix2 = 11;
static_assert(kRadix0 + kRadix1 + kRadix2 == 32, \"radix split must cover the key\");
constexpr int kShift0 = kRadix1 + kRadix2;
constexpr int kShift1 = kRadix2;
constexpr int kShift2 = 0;
constexpr int kBins0 = 1 << kRadix0;
constexpr int kBins1 = 1 << kRadix1;
constexpr int kBins2 = 1 << kRadix2;
constexpr int kPositions = 2 * kThreads;
static_assert(kBins0 <= kPositions, \"scan must cover level 0 bins\");

constexpr unsigned kSign = 0x80000000u;
constexpr unsigned kFullMask = 0xffffffffu;
constexpr int kNoFilter = 32;

// Cutoff rule: the largest bin whose suffix sum is >= target (or > target when
// the target is not positive, so empty bins above the data are never chosen).
enum class Bound { inclusive, exclusive };

__device__ __forceinline__ unsigned encode(float value) {
  const unsigned bits = __float_as_uint(value);
  return (bits & kSign) ? ~bits : (bits | kSign);
}

__device__ __forceinline__ float decode(unsigned key) {
  return __uint_as_float((key & kSign) ? (key & ~kSign) : ~key);
}

__device__ __forceinline__ double warp_scan(double value, int lane) {
#pragma unroll
  for (int offset = 1; offset < kLanes; offset <<= 1) {
    const double peer = __shfl_up_sync(kFullMask, value, offset);
    if (lane >= offset) value += peer;
  }
  return value;
}

struct Scratch {
  double hist[kPositions];
  double warp_offset[kWarps];
  double total;
  double above;
  double group;
  int crossing;
};

__device__ __forceinline__ void reset(Scratch& scratch, int bins) {
  for (int i = threadIdx.x; i < bins; i += kThreads) scratch.hist[i] = 0.0;
  if (threadIdx.x == 0) scratch.crossing = -1;
}

// Fills scratch.crossing/above/group/total for the current histogram.
__device__ void locate(Scratch& scratch, int bins, double target, Bound bound) {
  const int tid = threadIdx.x;
  const int lane = tid % kLanes;
  const int warp = tid / kLanes;
  __syncthreads();

  // Thread tid owns the ascending bin pair (2*tid, 2*tid+1).
  const double first = (2 * tid < bins) ? scratch.hist[2 * tid] : 0.0;
  const double second = (2 * tid + 1 < bins) ? scratch.hist[2 * tid + 1] : 0.0;
  const double pair = first + second;

  const double inclusive = warp_scan(pair, lane);
  if (lane == kLanes - 1) scratch.warp_offset[warp] = inclusive;
  __syncthreads();
  if (warp == 0) {
    const double carry = (lane < kWarps) ? scratch.warp_offset[lane] : 0.0;
    const double scanned = warp_scan(carry, lane);
    scratch.warp_offset[lane] = scanned - carry;
  }
  __syncthreads();

  const double exclusive = scratch.warp_offset[warp] + (inclusive - pair);
  if (tid == kThreads - 1) scratch.total = exclusive + pair;

  int candidate = -1;
  const double limit = exclusive + pair;  // placeholder, replaced below
  (void)limit;
  __syncthreads();

  // A bin qualifies when the sum of every bin at or above it still reaches the
  // target; the largest qualifying bin holds the crossing element.
  const double budget = scratch.total - target;
  if (2 * tid < bins && (bound == Bound::inclusive ? exclusive <= budget : exclusive < budget))
    candidate = 2 * tid;
  if (2 * tid + 1 < bins &&
      (bound == Bound::inclusive ? exclusive + first <= budget : exclusive + first < budget))
    candidate = 2 * tid + 1;
  if (candidate >= 0) atomicMax(&scratch.crossing, candidate);
  __syncthreads();

  if (scratch.crossing == 2 * tid || scratch.crossing == 2 * tid + 1) {
    const double prefix = (scratch.crossing == 2 * tid) ? exclusive : exclusive + first;
    scratch.above = scratch.total - (prefix + scratch.hist[scratch.crossing]);
    scratch.group = scratch.hist[scratch.crossing];
  }
  __syncthreads();
}

template <int BinShift, int BinMask, int FilterShift>
__device__ __forceinline__ void sweep(Scratch& scratch, const float* row, int width,
                                      unsigned filter) {
  const int tid = threadIdx.x;
  const int vectors = width >> 2;
  const float4* packed = reinterpret_cast<const float4*>(row);
  for (int i = tid; i < vectors; i += kThreads) {
    const float4 v = packed[i];
    const unsigned kx = encode(v.x);
    const unsigned ky = encode(v.y);
    const unsigned kz = encode(v.z);
    const unsigned kw = encode(v.w);
    if (FilterShift == kNoFilter || (kx >> (32 - FilterShift)) == filter)
      atomicAdd(&scratch.hist[(kx >> BinShift) & BinMask], (double)v.x);
    if (FilterShift == kNoFilter || (ky >> (32 - FilterShift)) == filter)
      atomicAdd(&scratch.hist[(ky >> BinShift) & BinMask], (double)v.y);
    if (FilterShift == kNoFilter || (kz >> (32 - FilterShift)) == filter)
      atomicAdd(&scratch.hist[(kz >> BinShift) & BinMask], (double)v.z);
    if (FilterShift == kNoFilter || (kw >> (32 - FilterShift)) == filter)
      atomicAdd(&scratch.hist[(kw >> BinShift) & BinMask], (double)v.w);
  }
  for (int i = (vectors << 2) + tid; i < width; i += kThreads) {
    const float value = row[i];
    const unsigned key = encode(value);
    if (FilterShift == kNoFilter || (key >> (32 - FilterShift)) == filter)
      atomicAdd(&scratch.hist[(key >> BinShift) & BinMask], (double)value);
  }
}

// threshold < 0 marks the retain-everything case (row sum below the target).
__device__ __forceinline__ void emit(const float* row, float* out, int width, float cutoff,
                                     double inverse, bool keep_all) {
  const int tid = threadIdx.x;
  const int vectors = width >> 2;
  const float4* packed = reinterpret_cast<const float4*>(row);
  float4* stores = reinterpret_cast<float4*>(out);
  for (int i = tid; i < vectors; i += kThreads) {
    const float4 v = packed[i];
    float4 r;
    r.x = (keep_all || v.x >= cutoff) ? (float)((double)v.x * inverse) : 0.0f;
    r.y = (keep_all || v.y >= cutoff) ? (float)((double)v.y * inverse) : 0.0f;
    r.z = (keep_all || v.z >= cutoff) ? (float)((double)v.z * inverse) : 0.0f;
    r.w = (keep_all || v.w >= cutoff) ? (float)((double)v.w * inverse) : 0.0f;
    stores[i] = r;
  }
  for (int i = (vectors << 2) + tid; i < width; i += kThreads) {
    const float value = row[i];
