  const float* values = probs.data_ptr<float>();
  const float* thresholds = top_p.data_ptr<float>();
  float* output = renorm_probs.data_ptr<float>();

  hist0_kernel<<<partial_grid, kThreads, 0, stream>>>(values, workspace.partials, (int)width, chunk);
  scan0_kernel<<<row_grid, kThreads, 0, stream>>>(workspace.partials, thresholds, workspace.counts,
                                                 workspace.plan);
  collect_kernel<<<partial_grid, kThreads, 0, stream>>>(values, workspace.plan, workspace.keys,
                                                        workspace.counts, (int)width, chunk);
  refine_kernel<<<row_grid, kThreads, 0, stream>>>(workspace.keys, workspace.counts, workspace.plan,
                                                   thresholds, workspace.epilogue, chunk);
  emit_kernel<<<partial_grid, kThreads, 0, stream>>>(values, output, workspace.epilogue, (int)width,
                                                     chunk);
  const cudaError_t error = cudaGetLastError();
  TORCH_CHECK(error == cudaSuccess, "top_p launch failed: ", cudaGetErrorString(error));
}
}  // namespace

