// Top-p renormalization over dense row probabilities.
//
// Every row is solved by a three level radix select over the monotone unsigned
// encoding of the float32 probability. Bin masses accumulate as fixed-point
// integers split into two 32-bit halves, so each update is a native shared
// integer atomic; the halves are concatenated exactly when a bin sum is read.
//
//   key      : order preserving uint32 of a probability
//   level 0  : bins over key bits [31:21]  (2048 bins)
//   level 1  : bins over key bits [20:11]  (1024 bins, inside the level 0 bin)
//   level 2  : bins over key bits [10:0]   (2048 bins, exactly one key per bin)
//
// Each row is cut into kChunks contiguous partitions so a launch covers the
// whole device instead of one CTA per row:
//
//   pass 1  hist<level>  per-partition histogram of the row partition
//   pass 2  emit         out = p / sum{p >= cutoff}, else 0
//
// A level's partials are merged by the partition that arrives last: each CTA
// fences its partials, then bumps a per-row ticket. The CTA that takes the last
// ticket merges every partial, resolves the crossing bin, and publishes the plan
// the next level filters with. Nothing is zeroed: the ticket is compared modulo
// kChunks, so the same slots survive across calls.
#include <torch/extension.h>

#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>

namespace {

constexpr int kThreads = 1024;
constexpr int kChunks = 4;  // row partitions, one CTA each
constexpr int kBatch = 4;   // float4 vectors in flight per thread
constexpr int kLanes = 32;
constexpr int kWarps = kThreads / kLanes;

// Radix split of the 32-bit monotone key.
constexpr int kRadix0 = 11;
constexpr int kRadix1 = 10;
constexpr int kRadix2 = 11;
static_assert(kRadix0 + kRadix1 + kRadix2 == 32, \"radix split must cover the key\");
constexpr int kShift0 = kRadix1 + kRadix2;
constexpr int kShift1 = kRadix2;
constexpr int kShift2 = 0;
constexpr int kBins0 = 1 << kRadix0;
constexpr int kBins1 = 1 << kRadix1;
constexpr int kBins2 = 1 << kRadix2;

constexpr unsigned kSign = 0x80000000u;
constexpr unsigned kFullMask = 0xffffffffu;
constexpr int kAllKeys = 0;  // sweep filter: keep every key

// Bin sums are held as fixed point integers split into two 32-bit halves, so
// every update is a native shared integer atomic (64-bit shared atomics compile
// to a CAS spin loop). Probabilities are bounded by one, so the low half of a
// whole row (kWidth * 2"'^(kLoBits-1)) stays below 2''^32 and the high half inside
// 2''^31; the split is therefore exact, and the only loss is the per-term rounding
// to 2''^-kFracBits, whose row-wide bound (kWidth * 2''^-(kFracBits+1)) stays two
// orders of magnitude below the smallest observed selection margin.
constexpr int kFracBits = 46;
constexpr int kLoBits = 15;
constexpr unsigned kLoMask = (1u << kLoBits) - 1;
constexpr unsigned long long kFracUnit = 1ull << kFracBits;
constexpr unsigned kMantissaMask = 0x7FFFFFu;
constexpr unsigned kMantissaBit = 0x800000u;
constexpr int kExponentBias = 127;
constexpr int kMantissaBits = 23;
constexpr int kShiftBase = kExponentBias + kMantissaBits - kFracBits;
constexpr int kMaxShift = kFracBits - 24;  // one is the largest representable value
constexpr int64_t kMaxWidth = 1 << 17;

using Fixed = unsigned long long;

__device__ __forceinline__ unsigned encode(float value) {
  const unsigned bits = __float_as_uint(value);
  return (bits & kSign) ? ~bits : (bits | kSign);
}

__device__ __forceinline__ float decode(unsigned key) {
  return __uint_as_float((key & kSign) ? (key & ~kSign) : ~key);
}

// Fixed-point image of a positive probability, rounded to nearest. Values at or
// below 2''^-kFracBits collapse to zero, which no selection decision can reach.
__device__ __forceinline__ Fixed fixed_of(unsigned bits) {
  const int shift = (int)((bits >> kMantissaBits) & 0xFFu) - kShiftBase;
  const unsigned mantissa = (bits & kMantissaMask) | kMantissaBit;
  if (shift >= 0) {
    if (shift > kMaxShift) return kFracUnit - 1;  // saturate at one
    return (Fixed)mantissa << shift;
  }
  const int down = -shift;
  if (down > 63) return 0ull;
  return ((Fixed)mantissa + (1ull << (down - 1))) >> down;
}

__device__ __forceinline__ Fixed warp_scan(Fixed value, int lane) {
#pragma unroll
  for (int offset = 1; offset < kLanes; offset <<= 1) {
    const Fixed peer = __shfl_up_sync(kFullMask, value, offset);
    if (lane >= offset) value += peer;
  }
  return value;
}

// Suffix sums are compared against the target either inclusively (positive
// target) or exclusively (target pinned at zero), so empty bins above the data
// can never be selected when the target is not positive.
enum class Bound { inclusive, exclusive };

struct Scratch {
  unsigned high[kBins0];
  unsigned low[kBins0];
  Fixed warp_offset[kWarps];
  Fixed total;
  Fixed above;
  Fixed group;
  int crossing;
};

// Per-row state carried between levels.
struct Plan {
  Fixed total;
  Fixed above;   // mass strictly above the current bin
  unsigned filter;  // key prefix the next level keeps
  int bin;          // crossing bin of the current level
  int keep_all;
};

// Everything the emit pass needs: cutoff and renormalization factor.
struct Epilogue {
  double inverse;
  float cutoff;
  int keep_all;
};

__device__ __forceinline__ Fixed bin_sum(const Scratch& scratch, int bin) {
  return ((Fixed)scratch.high[bin] << kLoBits) + scratch.low[bin];
}

__device__ __forceinline__ void reset(Scratch& scratch, int bins) {
  for (int i = threadIdx.x; i < bins; i += blockDim.x) {
    scratch.high[i] = 0u;
    scratch.low[i] = 0u;
  }
  if (threadIdx.x == 0) scratch.crossing = -1;
  __syncthreads();
}

template <int FilterBits>
__device__ __forceinline__ bool selected(unsigned key, unsigned filter) {
  if constexpr (FilterBits == kAllKeys) return true;
  else return (key >> (32 - FilterBits)) == filter;
}

__device__ __forceinline__ void accumulate(Scratch& scratch, int bin, Fixed value) {
  atomicAdd(&scratch.high[bin], (unsigned)(value >> kLoBits));
  atomicAdd(&scratch.low[bin], (unsigned)(value & kLoMask));
}

template <int BinShift, int BinMask, int FilterBits>
__device__ __forceinline__ void consume(Scratch& scratch, const float4 v, unsigned filter) {
  const unsigned kx = encode(v.x);
  const unsigned ky = encode(v.y);
  const unsigned kz = encode(v.z);
  const unsigned kw = encode(v.w);
  if (selected<FilterBits>(kx, filter))
    accumulate(scratch, (kx >> BinShift) & BinMask, fixed_of(__float_as_uint(v.x)));
  if (selected<FilterBits>(ky, filter))
    accumulate(scratch, (ky >> BinShift) & BinMask, fixed_of(__float_as_uint(v.y)));
  if (selected<FilterBits>(kz, filter))
    accumulate(scratch, (kz >> BinShift) & BinMask, fixed_of(__float_as_uint(v.z)));
  if (selected<FilterBits>(kw, filter))
    accumulate(scratch, (kw >> BinShift) & BinMask, fixed_of(__float_as_uint(v.w)));
}

// Row partitions are read in batches of kBatch vectors so several loads are in
// flight before the first dependent bin update.
template <int BinShift, int BinMask, int FilterBits>
__device__ __forceinline__ void sweep(Scratch& scratch, const float* row, int length,
                                      unsigned filter) {
  const int tid = threadIdx.x;
  const int vectors = length >> 2;
  const float4* packed = reinterpret_cast<const float4*>(row);

  int index = tid;
  for (; index + (kBatch - 1) * kThreads < vectors; index += kBatch * kThreads) {
    float4 batch[kBatch];
#pragma unroll
    for (int j = 0; j < kBatch; ++j) batch[j] = packed[index + j * kThreads];
#pragma unroll
    for (int j = 0; j < kBatch; ++j)
      consume<BinShift, BinMask, FilterBits>(scratch, batch[j], filter);
  }
  for (; index < vectors; index += kThreads)
    consume<BinShift, BinMask, FilterBits>(scratch, packed[index], filter);

  for (int i = (vectors << 2) + tid; i < length; i += kThreads) {
    const float value = row[i];
    const unsigned key = encode(value);
    if (selected<FilterBits>(key, filter))
      accumulate(scratch, (key >> BinShift) & BinMask, fixed_of(__float_as_uint(value)));
  }
}

// Largest bin whose suffix sum still reaches the remaining target.
__device__ void locate(Scratch& scratch, int bins, Fixed target, Bound bound) {
  const int tid = threadIdx.x;
  const int lane = tid % kLanes;
  const int warp = tid / kLanes;
  __syncthreads();  // the sweep'"'s histogram atomics must be visible

  // Thread tid owns the ascending bin pair (2*tid, 2*tid+1).
  const Fixed first = (2 * tid < bins) ? bin_sum(scratch, 2 * tid) : 0ull;
  const Fixed second = (2 * tid + 1 < bins) ? bin_sum(scratch, 2 * tid + 1) : 0ull;
  const Fixed pair = first + second;

  const Fixed inclusive = warp_scan(pair, lane);
  if (lane == kLanes - 1) scratch.warp_offset[warp] = inclusive;
  __syncthreads();
  if (warp == 0) {
    const Fixed carry = (lane < kWarps) ? scratch.warp_offset[lane] : 0ull;
    const Fixed scanned = warp_scan(carry, lane);
    scratch.warp_offset[lane] = scanned - carry;
  }
  __syncthreads();

  const Fixed exclusive = scratch.warp_offset[warp] + (inclusive - pair);
  if (tid == kThreads - 1) scratch.total = exclusive + pair;
  const Fixed first_limit = exclusive;
  const Fixed second_limit = exclusive + first;
  __syncthreads();

  const Fixed total = scratch.total;
  const bool reachable = total >= target;
  const Fixed budget = reachable ? total - target : 0ull;
  int candidate = -1;
  if (reachable && 2 * tid < bins &&
      (bound == Bound::inclusive ? first_limit <= budget : first_limit < budget))
    candidate = 2 * tid;
  if (reachable && 2 * tid + 1 < bins &&
      (bound == Bound::inclusive ? second_limit <= budget : second_limit < budget))
    candidate = 2 * tid + 1;
  if (candidate >= 0) atomicMax(&scratch.crossing, candidate);
  __syncthreads();

  if (scratch.crossing == 2 * tid || scratch.crossing == 2 * tid + 1) {
    const Fixed limit = (scratch.crossing == 2 * tid) ? first_limit : second_limit;
    scratch.group = bin_sum(scratch, scratch.crossing);
    scratch.above = total - (limit + scratch.group);
  }
  __syncthreads();
}

// Fixed-point target for a row threshold, plus the comparison style it needs.
__device__ __forceinline__ Fixed target_of(float top_p, Bound& bound) {
  const double raw = (double)top_p;
  const Fixed target = (raw > 0.0) ? (Fixed)(raw * (double)kFracUnit + 0.5) : 0ull;
  bound = (target > 0ull) ? Bound::inclusive : Bound::exclusive;
  return target;
}

// Merge the kChunks partial histograms of this row, resolve the crossing bin,
// and publish the plan the next level reads.
template <int Bins, int Radix>
__device__ void resolve(Scratch& scratch, const unsigned* partials, const float* top_p,
                        Plan* plan, unsigned* tickets, int row) {
  const int tid = threadIdx.x;
  reset(scratch, Bins);
  for (int bin = tid; bin < Bins; bin += blockDim.x) {
    unsigned high = 0u;
    unsigned low = 0u;
    for (int c = 0; c < kChunks; ++c) {
      const unsigned* slot = partials + ((size_t)row * kChunks + c) * (2 * kBins0);
      high += slot[bin];
      low += slot[kBins0 + bin];
    }
    scratch.high[bin] = high;
    scratch.low[bin] = low;
  }

  const Plan entry = plan[row];
  if (entry.keep_all) return;
  Bound bound;
  const Fixed target = target_of(top_p[row], bound);
  const Fixed below = (entry.above < target) ? entry.above : target;
  locate(scratch, Bins, target - below, bound);
  if (tid "'!= 0) return;

  Plan next;
  next.total = scratch.total;
  next.above = entry.above + scratch.above;
  next.bin = scratch.crossing;
  next.filter = (entry.filter << Radix) | (unsigned)(scratch.crossing < 0 ? 0 : scratch.crossing);
  next.keep_all = entry.keep_all || scratch.crossing < 0;
  plan[row] = next;
}

// Pass: histogram of one row partition at one radix level. The partition that
// takes the last ticket merges the partials and resolves the level.
template <int BinShift, int BinMask, int Bins, int Radix, int FilterBits>
__global__ void __launch_bounds__(kThreads) hist_kernel(const float* __restrict__ probs,
                                                        const Plan* __restrict__ plan_in,
                                                        Plan* __restrict__ plan_out,
                                                        const float* __restrict__ top_p,
                                                        unsigned* __restrict__ partials,
                                                        unsigned* __restrict__ tickets,
                                                        int width, int chunk) {
  __shared__ Scratch scratch;
  __shared__ int is_last;
  const int row = blockIdx.y;
  const int part = blockIdx.x;
  const int base = part * chunk;
  const int length = min(chunk, max(0, width - base));
  const unsigned filter = (FilterBits == kAllKeys) ? 0u : plan_in[row].filter;

  if (threadIdx.x == 0) is_last = 0;
  reset(scratch, Bins);
  if (!plan_in[row].keep_all)
    sweep<BinShift, BinMask, FilterBits>(scratch, probs + (size_t)row * width + base, length,
                                         filter);
  __syncthreads();

  unsigned* slot = partials + ((size_t)row * kChunks + part) * (2 * kBins0);
  for (int i = threadIdx.x; i < Bins; i += blockDim.x) {
    slot[i] = scratch.high[i];
    slot[kBins0 + i] = scratch.low[i];
  }

  // Release the partials, then let the last arrival of the row take the merge.
  __threadfence();
  __syncthreads();
  if (threadIdx.x == 0)
    is_last = ((atomicAdd(&tickets[row], 1u) % (unsigned)kChunks) == (unsigned)(kChunks - 1));
  __syncthreads();
  if (!is_last) return;
  resolve<Bins, Radix>(scratch, partials, top_p, plan_out, tickets, row);
}

// Pass: renormalize the retained probabilities.
__global__ void __launch_bounds__(kThreads) emit_kernel(const float* __restrict__ probs,
                                                        float* __restrict__ out,
                                                        const Epilogue* __restrict__ epilogue,
                                                        int width, int chunk) {
  const int row = blockIdx.y;
  const int part = blockIdx.x;
  const Epilogue entry = epilogue[row];

  const int base = part * chunk;
  const int length = min(chunk, max(0, width - base));
  const float* row_data = probs + (size_t)row * width + base;
  float* out_data = out + (size_t)row * width + base;
  const float cutoff = entry.cutoff;
  const float inverse = (float)entry.inverse;
  const bool keep_all = entry.keep_all != 0;

  const int vectors = length >> 2;
  const float4* packed = reinterpret_cast<const float4*>(row_data);
  float4* stores = reinterpret_cast<float4*>(out_data);
  int index = threadIdx.x;
  for (; index + (kBatch - 1) * kThreads < vectors; index += kBatch * kThreads) {
    float4 batch[kBatch];
#pragma unroll
    for (int j = 0; j < kBatch; ++j) batch[j] = packed[index + j * kThreads];
#pragma unroll
    for (int j = 0; j < kBatch; ++j) {
      const float4 v = batch[j];
      float4 r;
      r.x = (keep_all || v.x >= cutoff) ? v.x * inverse : 0.0f;
      r.y = (keep_all || v.y >= cutoff) ? v.y * inverse : 0.0f;
      r.z = (keep_all || v.z >= cutoff) ? v.z * inverse : 0.0f;
      r.w = (keep_all || v.w >= cutoff) ? v.w * inverse : 0.0f;
      stores[index + j * kThreads] = r;
    }
  }
  for (; index < vectors; index += kThreads) {
    const float4 v = packed[index];
    float4 r;
    r.x = (keep_all || v.x >= cutoff) ? v.x * inverse : 0.0f;
    r.y = (keep_all || v.y >= cutoff) ? v.y * inverse : 0.0f;
    r.z = (keep_all || v.z >= cutoff) ? v.z * inverse : 0.0f;
    r.w = (keep_all || v.w >= cutoff) ? v.w * inverse : 0.0f;
    stores[index] = r;
  }
  for (int i = (vectors << 2) + threadIdx.x; i < length; i += kThreads) {
    const float value = row_data[i];
    out_data[i] = (keep_all || value >= cutoff) ? value * inverse : 0.0f;
  }
}

// Last level: the crossing bin of level 2 names the cutoff key exactly.
__global__ void __launch_bounds__(kThreads) finish_kernel(const Plan* __restrict__ plan,
                                                          Epilogue* __restrict__ epilogue) {
  const int row = blockIdx.x;
  if (threadIdx.x != 0) return;
  const Plan entry = plan[row];

  Epilogue out;
  // An empty row keeps the zero output; a row that never reaches its target is
  // renormalized whole.
  out.keep_all = entry.total != 0ull;
  out.cutoff = entry.keep_all ? 0.0f : decode(entry.filter);
  out.inverse = entry.total == 0ull ? 0.0 : (double)kFracUnit / (double)entry.total;
  epilogue[row] = out;
}

// One device scratch block, cached across calls.
struct Workspace {
  char* raw = nullptr;
  size_t bytes = 0;
  unsigned* partials = nullptr;
  unsigned* tickets = nullptr;
  Plan* plan = nullptr;
  Epilogue* epilogue = nullptr;
};

void* reserve(Workspace& workspace, size_t bytes) {
  if (workspace.bytes >= bytes) return workspace.raw;
  if (workspace.raw != nullptr) cudaFree(workspace.raw);
  void* raw = nullptr;
  if (cudaMalloc(&raw, bytes) != cudaSuccess) {
    cudaGetLastError();
    workspace = Workspace{};
    return nullptr;
  }
  workspace.raw = (char*)raw;
  workspace.bytes = bytes;
  return raw;
}

void kernel(const torch::Tensor& probs, const torch::Tensor& top_p, torch::Tensor& renorm_probs) {
  TORCH_CHECK(probs.is_cuda() && top_p.is_cuda() && renorm_probs.is_cuda(), "expected CUDA tensors");
  TORCH_CHECK(probs.scalar_type() == torch::kFloat32 && top_p.scalar_type() == torch::kFloat32 &&
                  renorm_probs.scalar_type() == torch::kFloat32,
              "expected float32");
  TORCH_CHECK(probs.dim() == 2 && top_p.dim() == 1 && renorm_probs.dim() == 2, "unexpected rank");
  TORCH_CHECK(probs.is_contiguous() && top_p.is_contiguous() && renorm_probs.is_contiguous(),
              "expected contiguous tensors");
  const int64_t rows = probs.size(0);
  const int64_t width = probs.size(1);
  TORCH_CHECK(top_p.size(0) == rows, "top_p shape mismatch");
  TORCH_CHECK(renorm_probs.size(0) == rows && renorm_probs.size(1) == width, "output shape mismatch");
  TORCH_CHECK(probs.device() == top_p.device() && probs.device() == renorm_probs.device(),
              "device mismatch");
  if (rows == 0 || width == 0) return;
  TORCH_CHECK(width <= kMaxWidth, "row width exceeds the fixed-point split range");

  const int chunk = (int)(((width + kChunks - 1) / kChunks + 3) & ~(int64_t)3);
  const dim3 part_grid(kChunks, (unsigned)rows);
  const dim3 row_grid((unsigned)rows);
  const size_t partial_bytes = (size_t)rows * kChunks * 2 * kBins0 * sizeof(unsigned);
  const size_t ticket_bytes = (size_t)rows * sizeof(unsigned);
  const size_t plan_bytes = (size_t)rows * sizeof(Plan);
  const size_t epilogue_bytes = (size_t)rows * sizeof(Epilogue);

  c10::cuda::CUDAGuard guard(probs.device());
  static Workspace workspace;
  const size_t total = partial_bytes + ticket_bytes + plan_bytes + epilogue_bytes;
  if (reserve(workspace, total) == nullptr) TORCH_CHECK(false, "top_p workspace allocation failed");
  char* cursor = workspace.raw;
  workspace.partials = (unsigned*)cursor;
  cursor += partial_bytes;
  workspace.tickets = (unsigned*)cursor;
  cursor += ticket_bytes;
  workspace.plan = (Plan*)cursor;
  cursor += plan_bytes;
  workspace.epilogue = (Epilogue*)cursor;

  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(probs.get_device()).stream();
  const float* values = probs.data_ptr<float>();
  const float* thresholds = top_p.data_ptr<float>();
  float* output = renorm_probs.data_ptr<float>();
  const int width_i = (int)width;

  hist_kernel<kShift0, kBins0 - 1, kBins0, kRadix0, kAllKeys>
      <<<part_grid, kThreads, 0, stream>>>(values, workspace.plan, workspace.plan, thresholds,
                                           workspace.partials, workspace.tickets, width_i, chunk);
  hist_kernel<kShift1, kBins1 - 1, kBins1, kRadix1, kRadix0>
      <<<part_grid, kThreads, 0, stream>>>(values, workspace.plan, workspace.plan, thresholds,
                                           workspace.partials, workspace.tickets, width_i, chunk);
  hist_kernel<kShift2, kBins2 - 1, kBins2, kRadix2, kRadix0 + kRadix1>
      <<<part_grid, kThreads, 0, stream>>>(values, workspace.plan, workspace.plan, thresholds,
                                           workspace.partials, workspace.tickets, width_i, chunk);
  finish_kernel<<<row_grid, kThreads, 0, stream>>>(workspace.plan, workspace.epilogue);
  emit_kernel<<<part_grid, kThreads, 0, stream>>>(values, output, workspace.epilogue, width_i, chunk);
  const cudaError_t error = cudaGetLastError();
  TORCH_CHECK(error == cudaSuccess, "top_p launch failed: ", cudaGetErrorString(error));
}
}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) { module.def("kernel", &kernel); }
