}

__global__ void __launch_bounds__(kThreads) top_p_kernel(const float* __restrict__ probs,
                                                         const float* __restrict__ top_p,
                                                         float* __restrict__ out, int width) {
  __shared__ Scratch scratch;
  const int row_index = blockIdx.x;
  const float* row = probs + (size_t)row_index * width;
  float* out_row = out + (size_t)row_index * width;

  // A non-positive threshold keeps the single best token, so pin the target at
  // zero and require a strict suffix comparison.
  const double raw = (double)top_p[row_index];
  const Fixed target = (raw > 0.0) ? (Fixed)(raw * (double)kFracUnit + 0.5) : 0ull;
  const Bound bound = (target > 0ull) ? Bound::inclusive : Bound::exclusive;

  reset(scratch, kBins0);
  sweep<kShift0, kBins0 - 1, kAllRows>(scratch, row, width, 0u);
  locate(scratch, kBins0, target, bound);
  const Fixed row_total = scratch.total;
  if (row_total == 0ull) {  // degenerate empty row
    emit(row, out_row, width, 1.0f, 0.0, false);
    return;
  }
  if (scratch.crossing < 0) {  // the row never reaches the target: keep it all
    emit(row, out_row, width, 0.0f, (double)kFracUnit / (double)row_total, true);
    return;
  }

  const unsigned bin0 = (unsigned)scratch.crossing;
  Fixed above = scratch.above;

  reset(scratch, kBins1);
  sweep<kShift1, kBins1 - 1, kRadix0>(scratch, row, width, bin0);
  locate(scratch, kBins1, target - above, bound);
  const unsigned bin1 = (unsigned)scratch.crossing;
  above += scratch.above;

  reset(scratch, kBins2);
  sweep<kShift2, kBins2 - 1, kRadix0 + kRadix1>(scratch, row, width, (bin0 << kRadix1) | bin1);
  locate(scratch, kBins2, target - above, bound);
  const unsigned key = (bin0 << kShift0) | (bin1 << kShift1) | (unsigned)scratch.crossing;
  const Fixed retained = above + scratch.group;

  if (retained > 0ull) {
    emit(row, out_row, width, decode(key), (double)kFracUnit / (double)retained, false);
    return;
  }
  emit(row, out_row, width, 0.0f, (double)kFracUnit / (double)row_total, true);
}

